def checked(raw,refs,owner=OWNER,function=FUNCTION):
 if owner!=OWNER or function!=FUNCTION or len(raw)!=548 or sha(raw)!=DERIVATION['raw_sha256']or refs!=SOURCE_REFS:raise ValueError('Motion-approach payload, bindings or scope changed')
 return raw,refs

def normalize(raw,refs):
 raw,refs=checked(raw,refs);w=list(struct.unpack('>137I',raw));assert w[8]==0x46007382 and w[10]==0x4600A502;w[8],w[10]=w[10],w[8];return struct.pack('>137I',*w),dict(refs)

def assemble(text,label):
 p=out/(label+'.s');p.write_text(text);q=p.with_suffix('.o');subprocess.run(['mips-linux-gnu-as','-EB','-march=vr4300','-mabi=32','-I',str(root/'conker/include'),'-o',str(q),str(p)],capture_output=True,check=True);return q

def emit(raw,refs,label):
 text='.set noat\n.set noreorder\n.set gp=64\n.text\n.globl '+FUNCTION+'\n.type '+FUNCTION+',@function\n'+FUNCTION+':\n'
 for i,(w,)in enumerate(struct.iter_unpack('>I',raw)):
  for kind,name in refs.get(i*4,[]):text+='.reloc ., '+kind+', '+name+'\n'
  text+='.word 0x%08X\n'%w
 return assemble(text+'.size '+FUNCTION+',.-'+FUNCTION+'\n',label)

def reference():
 truth=(root/'conker/conker.us.bin').read_bytes()[ROM:ROM+SIZE];assembly=(root/ASM).read_text();obj=assemble('.include "macro.inc"\n.set noat\n.set noreorder\n.set gp=64\n.text\n'+assembly+'\n.size '+FUNCTION+',.-'+FUNCTION+'\n','retail-linked');(out/'retail-layout.s').write_text(assembly);return truth,obj

def guard_rows(raw,refs,normal,nrefs):
 before=struct.unpack('>137I',raw);after=struct.unpack('>137I',normal);assert refs==nrefs;rows=[]
 for i in (8,10):
  assert i*4 not in refs
  rows.append(dict(filename=OWNER,function=FUNCTION,offset='0x%03X'%(i*4),expected='0x%08X'%before[i],replacement='0x%08X'%after[i],expected_relocations='-',replacement_relocations='-',note='Normalize two independent motion-rate multiplies',insert_after='',insert_after_relocations='',omit='false'))
 return rows

