def strict_image(before,actual,truth):
 assert sha(before)==FROZEN[ELF]and len(truth)==548
 expected=bytearray(before);at=elf_slot_offset(before,ENTRY,SIZE);expected[at:at+SIZE]=truth
 rows=[r for r in symbol_rows(before)if r[1]==FUNCTION];assert len(rows)==1 and rows[0][2][2]==32
 struct.pack_into('>I',expected,rows[0][0]+8,SIZE)
 # New undefined references perturb three closed GNU symbol-hash buckets.
 # Rebuild only these exact old records and their contiguous name strings.
 oldrows=symbol_rows(before);lookup={n:r for r in oldrows for n in (r[1],)}
 groups=[(('D_80038080','D_8009D670'),('D_8009D670','D_80038080')),(('func_151BC580','D_8009D6A0'),('D_8009D6A0','func_151BC580')),(('D_800994CC','D_800997E4','D_8009EECC'),('D_800997E4','D_8009EECC','D_800994CC'))]
 for oldnames,newnames in groups:
  entries=[lookup[n]for n in oldnames];slots=[r[0]for r in entries];starts=[r[3]for r in entries]
  assert all(sum(r[1]==n for r in oldrows)==1 for n in oldnames)and set(oldnames)==set(newnames)
  assert slots==list(range(slots[0],slots[0]+16*len(slots),16))
  assert all(starts[i+1]==starts[i]+len(oldnames[i])+1 for i in range(len(starts)-1))
  table_base=starts[0]-entries[0][2][0];position=starts[0]
  for slot,name in zip(slots,newnames):
   record=bytearray(before[lookup[name][0]:lookup[name][0]+16]);struct.pack_into('>I',record,0,position-table_base);expected[slot:slot+16]=record
   label=name.encode()+b'\0';expected[position:position+len(label)]=label;position+=len(label)
  assert position==starts[-1]+len(oldnames[-1])+1
 wanted=Counter((r[1],*r[2][1:2],SIZE if r[1]==FUNCTION else r[2][2],*r[2][3:])for r in oldrows)
 observed=Counter((r[1],*r[2][1:])for r in symbol_rows(actual));assert wanted==observed,'Named definition changed'
 assert bytes(expected)==actual,'Whole motion-approach ELF differs beyond closed body, size and record permutations'
 return sum(a!=b for a,b in zip(before,actual))

def padded(root,out,obj,guards,label,strict=False):
 folder=out/label;folder.mkdir(exist_ok=True);destination=folder/'game_83300.c.o';assembly=folder/'game_83300.c.o.padded.s';sys.modules.setdefault('pad_generated_object',pad_generated_object)
