 raw_neighbors=same_functions(before,after,(FUNCTION,));assert raw_neighbors==88 and sections(before)['.reginfo']==sections(after)['.reginfo']and normalized_pools(before)==normalized_pools(after)=={'.rodata':None,'.data':None}
 raw,refs=checked(*payload(after));normal,nrefs=normalize(raw,refs);truth,ref=reference();assert payload(ref)==(normal,nrefs)and struct.pack('>137I',*bound_blob(normal,nrefs,SYMS))==truth
 rows=guard_rows(raw,refs,normal,nrefs);assert rows==GUARD_ROWS;assert len(rows)==2;independent(raw,refs,rows);oldguard=(out/'frozen'/GUARDS).read_bytes();stream=io.StringIO(newline='');w=csv.DictWriter(stream,fieldnames=oldguard.splitlines()[0].decode().split(','),lineterminator='\r\n'if b'\r\n'in oldguard else'\n');w.writerows(rows);guard=out/'proposed-guards.csv';guard.write_bytes(oldguard+stream.getvalue().encode());assert guard.read_bytes()==guards(out)
 oldpad=padded(root,out,before,out/'frozen'/GUARDS,'predecessor-padded');newpad=padded(root,out,after,guard,'qualified-padded');padded_neighbors=same_functions(oldpad,newpad,(FUNCTION,));assert padded_neighbors==88 and normalized_pools(oldpad)==normalized_pools(newpad)and payload(newpad)==(normal,nrefs)
 assert(root/OBJECT).read_bytes()==(newpad if installed else oldpad).read_bytes();recipe=make_shadow(root,out,out/'final-owner.c',guard,newpad,after);oldelf=link(root,out,oldpad,'predecessor-image');newelf=link(root,out,newpad,'qualified-image');assert oldelf.read_bytes()==(out/'frozen'/ELF).read_bytes();assert(root/ELF).read_bytes()==(newelf if installed else oldelf).read_bytes();delta=strict_image(oldelf.read_bytes(),newelf.read_bytes(),truth)
 a,_,aa=load_elf_functions(str(oldelf),'mips-linux-gnu-objdump');b,_,bb=load_elf_functions(str(newelf),'mips-linux-gnu-objdump');assert a.keys()==b.keys()and aa==bb and set(n for n in b if a[n]!=b[n])=={FUNCTION}
 layout=audit_layout(newelf,root/'conker');assert layout['exact']and layout['different_bytes']==0
 report=dict(source_installed=installed,words=137,raw_words=137,frame=16,guards=len(rows),insertions=0,omissions=0,caller_declaration=caller,raw_neighbors=raw_neighbors,padded_neighbors=padded_neighbors,pools_equal=True,register_usage_unchanged=True,diagnostics_before=8,diagnostics_after=8,new_diagnostics=0,strict_unexplained_bytes=0,image_changed_bytes=delta,functions=len(a),all_addresses_fixed=True,actual_Make=recipe,protected_data=layout,ELF_sha256=sha(newelf.read_bytes()),owner_sha256=sha(newpad.read_bytes()),guard_sha256=sha(guard.read_bytes()));(out/'qualification.json').write_text(json.dumps(report,indent=2)+'\n');(out/'normalization.json').write_text(json.dumps(dict(guards=rows,sha256=sha(guard.read_bytes())),indent=2)+'\n');print(json.dumps(report),flush=True);return report

